with enriched as (select *, round(rating / sum(rating) over (partition by city), 4) as rating_share, row_number() over (partition by city order by rating, id) as event_seq, first_value(rating) ignore nulls over (partition by country order by rating, id rows between unbounded preceding and current row) as first_known_rating from suppliers) select country, city, percentile_approx(event_seq, array(0.25, 0.5, 0.75)) as event_seq_quartiles, size(collect_set(city)) as num_cities, sort_array(collect_set(city)) as city_list from enriched group by rollup (country, city) order by country
